"""Generate selected resize, exit and scratch instances from pinned source traces.

No allocator is simulated. This initial slice is not a whole-walk certificate.
"""
import gzip
import json
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[2]
data = json.loads(gzip.decompress((root / 'data/paper935/hmr-source-resize.json.gz').read_bytes()))
assert data['source_commit'] == '64b5a13aa249f1360846657392e6c66817b26d0f'
lines = ['import ECDSAAdd.Arithmetic.Paper935.HmrLoggedRows', '',
         'namespace ECDSAAdd.Arithmetic.Paper935', '',
         '/- Generated by scripts/paper935/generate_resize_instances.py.',
         'Initial headroom transactions only; not a whole-walk certificate. -/', '']
for phase in ('s2-walkA', 's6-walkC'):
    stage = next(s for s in data['stages'] if s['phase']==phase and s['step']==0 and s['stage']=='add')
    for r in stage['resizes'][4:]:
        name = phase[:2] + 'Initial' + r['row'].capitalize()
        intervals = ' ∨ '.join(f'({a} ≤ q ∧ q < {b})' for a,b in r['live_before'])
        fresh = r['after'][len(r['before']):]
        lines += [f'def {name}Arena : Arena :=',
                  f'  ⟨arenaWires.filter (fun q => {intervals}),Finset.filter_subset _ _⟩', '',
                  f'def {name}Row : WindowRow := ⟨{r["before"]},{r["sign"]}⟩', '',
                  f'def {name}Fresh : List Wire := {fresh}', '',
                  f'theorem {name}_checked :',
                  f'    (planRowResizeLog {name}Arena {name}Row {r["width"]} {name}Fresh).map (fun (_,out,_) => out) =',
                  f'      some ⟨{r["after"]},{r["sign"]}⟩ := by',
                  '  decide +kernel', '']
lines += ['end ECDSAAdd.Arithmetic.Paper935', '']
text = '\n'.join(lines)
path = root/'ECDSAAdd/Arithmetic/Paper935/HmrSourceResizeInitial.lean'
if '--check' in sys.argv:
    assert path.read_text()==text, 'Generated resize instances differ; regenerate from pinned log.'
else:
    path.write_text(text)

lines = ['import ECDSAAdd.Arithmetic.Paper935.HmrBankRepack', '',
         'namespace ECDSAAdd.Arithmetic.Paper935', '',
         '/- Generated from the same pinned trace. First shift-exit journals',
         'only; not an assertion of whole-walk source correspondence. -/', '']
for phase in ('s2-walkA', 's6-walkC'):
    stage = next(s for s in data['stages'] if s['phase']==phase and s['step']==0 and s['stage']=='shift_exit')
    assert len(stage['repacks'])==1
    record = stage['repacks'][0]
    before, after = record['before'], record['after']
    live = sorted(set(before['allocated']) - set(sum(before['free'].values(), [])))
    ranges = []
    for q in live:
        if ranges and ranges[-1][1]==q:
            ranges[-1][1]=q+1
        else:
            ranges.append([q,q+1])
    intervals = ' ∨ '.join(f'({a} ≤ q ∧ q < {b})' for a,b in ranges)
    moves = '[' + ', '.join(f'({m["old"]}, {m["fresh"]})' for m in record['moves']) + ']'
    name = phase[:2] + 'InitialExit'
    lines += [f'def {name}Arena : Arena :=',
              f'  ⟨arenaWires.filter (fun q => {intervals}),Finset.filter_subset _ _⟩', '',
              f'def {name}Moves : List (Wire × Wire) := {moves}', '']
    for suffix,snap in [('Before',before),('After',after)]:
        rows = ',\n    '.join(f'⟨{snap["rows"][row]["payload"]},{snap["rows"][row]["sign"]}⟩' for row in ('f','g','fv','gv'))
        lines += [f'def {name}{suffix} : WindowBank :=', f'  ⟨{rows}⟩', '']
    lines += [f'theorem {name}_checked :',
              f'    ({name}Arena.checkRepack {name}Moves).isSome = true := by',
              '  decide +kernel', '',
              f'theorem {name}_views :',
              f'    {name}Before.repacked {name}Moves={name}After := by',
              '  decide +kernel', '']
lines += ['end ECDSAAdd.Arithmetic.Paper935', '']
text = '\n'.join(lines)
path = root/'ECDSAAdd/Arithmetic/Paper935/HmrSourceExitInitial.lean'
if '--check' in sys.argv:
    assert path.read_text()==text, 'Generated exit instances differ; regenerate from pinned log.'
else:
    path.write_text(text)

lines = ['import ECDSAAdd.Arithmetic.Paper935.HmrLoggedExit',
         'import ECDSAAdd.Arithmetic.Paper935.HmrSourceExitInitial', '',
         'namespace ECDSAAdd.Arithmetic.Paper935', '',
         '/- Generated first-step resize-plus-repack instances. -/', '']
for phase in ('s2-walkA', 's6-walkC'):
    stage = next(s for s in data['stages'] if s['phase']==phase and s['step']==0 and s['stage']=='shift_exit')
    records = {r['row']: r for r in stage['resizes']}
    intervals = ' ∨ '.join(f'({a} ≤ q ∧ q < {b})' for a,b in stage['resizes'][0]['live_before'])
    name = phase[:2] + 'InitialExit'
    rows = ',\n    '.join(f'⟨{records[row]["before"]},{records[row]["sign"]}⟩' for row in ('f','g','fv','gv'))
    widths = ','.join(str(records[row]['width']) for row in ('f','g','fv','gv'))
    logs = [r['after'][len(r['before']):] for r in stage['resizes']]
    lines += [f'def {name}ResizeArena : Arena :=',
              f'  ⟨arenaWires.filter (fun q => {intervals}),Finset.filter_subset _ _⟩', '',
              f'def {name}ResizeBank : WindowBank :=', f'  ⟨{rows}⟩', '',
              f'theorem {name}_compiled :',
              f'    (compileHmrLoggedExit {name}ResizeArena {name}ResizeBank ⟨{widths}⟩',
              f'      {logs} {name}Moves).map (fun (_,out,_) => out)=some {name}After := by',
              '  decide +kernel', '']
lines += ['end ECDSAAdd.Arithmetic.Paper935', '']
text = '\n'.join(lines)
path = root/'ECDSAAdd/Arithmetic/Paper935/HmrSourceExitReplay.lean'
if '--check' in sys.argv:
    assert path.read_text()==text, 'Generated exit replay differs; regenerate from pinned log.'
else:
    path.write_text(text)

allocation = json.loads(gzip.decompress((root / 'data/paper935/hmr-source-allocations.json.gz').read_bytes()))
assert allocation['source_commit'] == data['source_commit']
lines = ['import ECDSAAdd.Arithmetic.Paper935.HmrLoggedCounter',
         'import ECDSAAdd.Arithmetic.Paper935.HmrLoggedHybridCin', '',
         'namespace ECDSAAdd.Arithmetic.Paper935', '',
         '/- Generated allocation examples: first early/armed counter stages',
         'and the first narrow (fv/gv) hybrid call, for each pinned walk. -/', '']
def arena_lines(name, ranges):
    intervals = ' ∨ '.join(f'({a} ≤ q ∧ q < {b})' for a,b in ranges)
    return [f'def {name}Arena : Arena :=',
            f'  ⟨arenaWires.filter (fun q => {intervals}),Finset.filter_subset _ _⟩', '']
for phase in ('s2-walkA', 's6-walkC'):
    for early in (True, False):
        stage = next(s for s in allocation['stages'] if s['phase']==phase and s['stage']=='counter' and s['early']==early)
        name = phase[:2] + ('Early' if early else 'Armed') + 'CounterLog'
        work = [e['wire'] for e in stage['events'] if e['kind']=='take']
        lines += arena_lines(name, stage['live_before'])
        lines += [f'def {name}Work : List Wire := {work}', '',
                  f'/-- Recorded step {stage["step"]}. The early control site is the retained sigma;',
                  'the early counter program ignores this control argument. -/',
                  f'theorem {name}_checked :',
                  f'    (compileHmrCounterStepLog {name}Arena {str(early).lower()} {stage["control"]}',
                  f'      {stage["counter"]} {name}Work).isSome = true := by',
                  '  decide +kernel', '']
    stage = next(s for s in allocation['stages'] if s['phase']==phase and s['step']==0 and s['stage']=='add')
    call = stage['calls'][1]
    live = {q for a,b in stage['live_before'] for q in range(a,b)}
    for event in stage['events'][:call['start']]:
        (live.add if event['kind']=='take' else live.remove)(event['wire'])
    ranges = []
    for q in sorted(live):
        if ranges and ranges[-1][1]==q: ranges[-1][1]=q+1
        else: ranges.append([q,q+1])
    name = phase[:2] + 'InitialNarrowLog'
    work = [e['wire'] for e in stage['events'][call['start']:call['end']] if e['kind']=='take']
    lines += arena_lines(name, ranges)
    lines += [f'def {name}Work : List Wire := {work}', '',
              f'theorem {name}_checked :',
              f'    (compileHmrHybridCinLog {name}Arena {call["control"]} {call["cin"]} {call["carry"]}',
              f'      {call["source"]} {call["target"]} {name}Work).isSome = true := by',
              '  decide +kernel', '']
lines += ['end ECDSAAdd.Arithmetic.Paper935', '']
text = '\n'.join(lines)
path = root/'ECDSAAdd/Arithmetic/Paper935/HmrSourceScratchInitial.lean'
if '--check' in sys.argv:
    assert path.read_text()==text, 'Generated scratch instances differ; regenerate from pinned log.'
else:
    path.write_text(text)
